(function(){
  var C = window.GreenhseCheckout;
  var $ = function(s){ return document.querySelector(s); };
  function param(n){
    var m = location.search.match(new RegExp('[?&]'+n+'=([^&]*)'));
    return m ? decodeURIComponent(m[1]) : null;
  }
  /* ANZ returns with the order reference in the query string; different
     Worldline configurations name it differently, so accept the usual set and
     fall back to what checkout stored before redirecting. */
  var num = param('order') || param('orderId') || param('incrementId') || param('reference');
  if(!num){ try{ num = sessionStorage.getItem('greenhse_last_order'); }catch(e){} }

  function paint(title, sub, status, next){
    $('#oc-title').textContent = title;
    $('#oc-sub').textContent = sub;
    $('#oc-status').textContent = status;
    $('#oc-num').textContent = num || '—';
    $('#oc-next').innerHTML = next || '';
  }

  var shopLinks = '<p style="margin-top:22px">'+
    '<a class="btn-s" href="/account/" style="text-decoration:none">View your orders</a> '+
    '<a class="btn-s" href="/categories/" style="text-decoration:none;margin-left:8px">Keep shopping</a></p>';

  if(!num){
    paint('We could not find your order',
      'If you were just paying, check your email for a confirmation before trying again.',
      'Unknown', shopLinks);
    return;
  }

  if(param('noredirect')){
    paint('Order received — payment still to come',
      'Your order is in our system but has not been paid yet. Call us on (08) 9297 2969 and we will take payment or send you a payment link.',
      'Awaiting payment',
      '<p style="margin-top:22px"><a class="btn-p" href="tel:+61892972969" style="text-decoration:none;display:inline-block">Call (08) 9297 2969</a></p>'+shopLinks);
    return;
  }

  /* Ask Magento what actually happened rather than trusting the return URL —
     a customer can land here having cancelled on ANZ's page. */
  C.finalise(num).then(function(r){
    if(r.paid === true){
      paint('Thanks — your order is confirmed',
        'We have emailed your receipt. Our Perth team will be in touch about delivery or pickup.',
        'Paid', shopLinks);
    } else if(r.paid === false){
      paint('Payment was not completed',
        'Your order is saved but unpaid — nothing has been charged. You can call us to pay, or place it again.',
        'Not paid',
        '<p style="margin-top:22px"><a class="btn-p" href="tel:+61892972969" style="text-decoration:none;display:inline-block">Call (08) 9297 2969</a></p>'+shopLinks);
    } else {
      paint('Order received',
        'We could not confirm the payment status automatically. If you completed payment, your receipt will arrive by email — call us if anything looks wrong.',
        'Awaiting confirmation', shopLinks);
    }
  }).catch(function(){
    paint('Order received',
      'We could not confirm the payment status automatically. Check your email for a receipt, or call us on (08) 9297 2969.',
      'Awaiting confirmation', shopLinks);
  });
})();

