(function(){
  var A = window.GreenhseAccount;
  var $ = function(s){ return document.querySelector(s); };

  function say(where, text, kind){
    var el = $(where);
    if(!text){ el.innerHTML=''; return; }
    el.innerHTML = '<div class="msg msg-'+(kind||'err')+'">'+text+'</div>';
    el.scrollIntoView({block:'nearest'});
  }
  /* Magento's messages are written for shoppers, so they are shown as-is —
     except the session one, which only makes sense as an instruction. */
  function human(e){
    if(e && e.message === 'SESSION_EXPIRED') return 'Your session timed out. Please sign in again.';
    if(e && e.message === 'NOT_SIGNED_IN') return 'Please sign in.';
    if(!navigator.onLine) return 'You appear to be offline. Check your connection and try again.';
    return (e && e.message) || 'Something went wrong. Please try again.';
  }
  function busy(btn, on, label){
    btn.disabled = on;
    if(on){ btn.dataset.was = btn.innerHTML; btn.innerHTML = '<span class="spin"></span>'+(label||'Working…'); }
    else if(btn.dataset.was){ btn.innerHTML = btn.dataset.was; }
  }

  /* ---- signed-out tabs ---- */
  function show(which){
    $('#form-in').hidden = which!=='in';
    $('#form-up').hidden = which!=='up';
    $('#form-reset').hidden = which!=='reset';
    $('#tab-in').classList.toggle('on', which==='in');
    $('#tab-up').classList.toggle('on', which==='up');
    say('#msg-area','');
  }
  $('#tab-in').onclick = function(){ show('in'); };
  $('#tab-up').onclick = function(){ show('up'); };
  $('#forgot').onclick = function(){ show('reset'); };
  $('#back-in').onclick = function(){ show('in'); };
  if(/[?&]new=1/.test(location.search)) show('up');

  /* Magento guards these three forms with reCAPTCHA, so each gets its own
     tick-box. If Google cannot be reached we say so plainly rather than
     letting the submit fail with a confusing server message. */
  var caps = {};
  ['in','up','rs'].forEach(function(k){
    A.mountCaptcha(document.getElementById('cap-'+k)).then(function(c){ caps[k]=c; })
     .catch(function(){
       document.getElementById('cap-'+k).innerHTML =
         '<p class="hint" style="margin:0">Verification could not load. Check your connection, '+
         'or call us on (08) 9297 2969.</p>';
     });
  });
  function capOf(k){
    var c = caps[k];
    if(!c) return null;
    var v = c.value();
    return v || null;
  }

  /* Where to go after signing in — checkout sends people here with ?next= */
  function next(){
    var m = location.search.match(/[?&]next=([^&]+)/);
    return m ? decodeURIComponent(m[1]) : null;
  }
  function afterAuth(){
    var n = next();
    if(n && /^\/[a-zA-Z0-9\-_\/.]*$/.test(n)) { location.href = n; return; }
    location.reload();
  }

  $('#form-in').onsubmit = function(e){
    e.preventDefault(); say('#msg-area','');
    var cap = capOf('in');
    if(!cap){ say('#msg-area','Please tick “I\u2019m not a robot” first.'); return; }
    var b = $('#li-go'); busy(b,true,'Signing in…');
    A.login($('#li-email').value.trim(), $('#li-pw').value, cap)
      .then(afterAuth)
      .catch(function(err){
        busy(b,false); if(caps['in']) caps['in'].reset();
        say('#msg-area', human(err));
      });
  };

  $('#form-up').onsubmit = function(e){
    e.preventDefault(); say('#msg-area','');
    var cap = capOf('up');
    if(!cap){ say('#msg-area','Please tick “I\u2019m not a robot” first.'); return; }
    var b = $('#su-go'); busy(b,true,'Creating…');
    var email = $('#su-email').value.trim();
    A.register({
      firstname: $('#su-first').value.trim(), lastname: $('#su-last').value.trim(),
      email: email, password: $('#su-pw').value,
      subscribe: $('#su-sub').checked, captcha: cap
    }).then(function(){
        busy(b,false);
        if(caps['up']) caps['up'].reset();
        show('in');
        $('#li-email').value = email;
        say('#msg-area','Account created. Sign in below to continue.','ok');
        $('#li-pw').focus();
      })
      .catch(function(err){
        busy(b,false); if(caps['up']) caps['up'].reset();
        say('#msg-area', human(err));
      });
  };

  $('#form-reset').onsubmit = function(e){
    e.preventDefault();
    var cap = capOf('rs');
    if(!cap){ say('#msg-area','Please tick “I\u2019m not a robot” first.'); return; }
    var b = $('#rs-go'); busy(b,true,'Sending…');
    A.requestPasswordReset($('#rs-email').value.trim(), cap).then(function(){
      if(caps['rs']) caps['rs'].reset();
      busy(b,false);
      say('#msg-area','If that email is on an account, a reset link is on its way. Check your inbox.','ok');
    }).catch(function(err){ busy(b,false); say('#msg-area', human(err)); });
  };

  /* ---- signed-in area ---- */
  function pane(which){
    $('#pane-ord').hidden = which!=='ord';
    $('#pane-det').hidden = which!=='det';
    $('#pane-addr').hidden = which!=='addr';
    $('#tab-ord').classList.toggle('on', which==='ord');
    $('#tab-det').classList.toggle('on', which==='det');
    $('#tab-addr').classList.toggle('on', which==='addr');
  }
  $('#tab-ord').onclick=function(){pane('ord');};
  $('#tab-det').onclick=function(){pane('det');};
  $('#tab-addr').onclick=function(){pane('addr');};

  function esc(s){ return String(s==null?'':s).replace(/[&<>"]/g, function(c){
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
  function money(v){ return '$'+Number(v||0).toFixed(2); }

  function loadAccount(){
    if(!A.signedIn()) return;
    A.me().then(function(c){
      $('#who').textContent = 'Signed in as '+c.firstname+' '+c.lastname+' ('+c.email+').';
      $('#details').innerHTML =
        '<div class="sline"><span>Name</span><b>'+esc(c.firstname+' '+c.lastname)+'</b></div>'+
        '<div class="sline"><span>Email</span><b>'+esc(c.email)+'</b></div>'+
        '<div class="sline"><span>Newsletter</span><b>'+(c.is_subscribed?'Subscribed':'Not subscribed')+'</b></div>';
      var ad = c.addresses||[];
      $('#addr-list').innerHTML = ad.length ? ad.map(function(a){
        return '<div class="ordrow"><div class="top"><span class="num">'+esc(a.firstname+' '+a.lastname)+'</span>'+
          (a.default_shipping?'<span class="st">Default delivery</span>':'')+'</div>'+
          '<div class="li">'+esc((a.street||[]).join(', '))+'</div>'+
          '<div class="li">'+esc(a.city)+' '+esc((a.region&&a.region.region_code)||'')+' '+esc(a.postcode)+'</div>'+
          '<div class="li">'+esc(a.telephone)+'</div></div>';
      }).join('') : '<p class="hint">No saved addresses yet.</p>';
    }).catch(function(err){
      if(err && err.expired){ location.reload(); return; }
      say('#msg-area-in', human(err));
    });

    A.orders().then(function(list){
      $('#orders').innerHTML = list.length ? list.map(function(o){
        var items = (o.items||[]).map(function(i){
          return '<div class="li">'+i.quantity_ordered+' × '+esc(i.product_name)+'</div>'; }).join('');
        return '<div class="ordrow"><div class="top">'+
          '<span class="num">Order '+esc(o.number)+'</span>'+
          '<span class="st">'+esc(o.status)+'</span></div>'+
          '<div class="li">'+esc(o.order_date)+' · <b>'+money(o.total&&o.total.grand_total&&o.total.grand_total.value)+'</b></div>'+
          items+'</div>';
      }).join('') : '<div class="empty"><p>No orders yet.</p><p style="margin-top:10px">'+
        '<a class="btn-s" href="/categories/" style="text-decoration:none">Browse the range</a></p></div>';
    }).catch(function(err){
      if(err && err.expired){ location.reload(); return; }
      $('#orders').innerHTML = '<div class="msg msg-err">'+human(err)+'</div>';
    });
  }

  $('#form-pw').onsubmit = function(e){
    e.preventDefault();
    var b = e.target.querySelector('button'); busy(b,true,'Updating…');
    A.changePassword($('#pw-cur').value, $('#pw-new').value).then(function(){
      busy(b,false); e.target.reset();
      say('#msg-area-in','Password updated.','ok');
    }).catch(function(err){ busy(b,false); say('#msg-area-in', human(err)); });
  };

  $('#form-addr').onsubmit = function(e){
    e.preventDefault();
    var b = e.target.querySelector('button'); busy(b,true,'Saving…');
    A.saveAddress({
      firstname:$('#ad-first').value.trim(), lastname:$('#ad-last').value.trim(),
      company:$('#ad-co').value.trim(), street:[$('#ad-st').value.trim()],
      city:$('#ad-city').value.trim(), postcode:$('#ad-pc').value.trim(),
      region:$('#ad-state').value, region_code:$('#ad-state').value,
      telephone:$('#ad-tel').value.trim(), default_shipping:true, default_billing:true
    }).then(function(){
      busy(b,false); e.target.reset();
      say('#msg-area-in','Address saved.','ok'); loadAccount();
    }).catch(function(err){ busy(b,false); say('#msg-area-in', human(err)); });
  };

  $('#signout').onclick = function(){
    A.logout().then(function(){ location.href='/'; });
  };

  if(A.signedIn()) loadAccount();
})();

