/* [hidden] must beat the display rules below, or a hidden panel still shows. */
[hidden]{display:none !important}
.shop{max-width:1080px;margin:0 auto;padding:44px 20px 72px}
.shop h1{font-size:2.1rem;margin-bottom:6px}
.shop .sub{color:#5d6151;margin-bottom:30px}
.shop-grid{display:grid;grid-template-columns:1.25fr .85fr;gap:34px;align-items:start}
@media(max-width:860px){.shop-grid{grid-template-columns:1fr}}
.panel-c{background:#fff;border:1px solid #dfe3d8;border-radius:9px;padding:24px 26px;margin-bottom:18px}
.panel-c h2{font-size:1.15rem;margin:0 0 4px}
.panel-c .hint{color:var(--ink-muted);font-size:.9rem;margin-bottom:16px}
.fld{margin-bottom:14px}
.fld label{display:block;font-weight:600;font-size:.9rem;margin-bottom:5px}
.fld input,.fld select{width:100%;padding:11px 12px;border:1px solid #cfcec2;border-radius:6px;font:inherit;background:#fff}
.fld input:focus,.fld select:focus{outline:2px solid #00a800;outline-offset:-1px;border-color:#00a800}
.row2{display:grid;grid-template-columns:1fr 1fr;gap:12px}
@media(max-width:560px){.row2{grid-template-columns:1fr}}
.btn-p{padding:13px 26px;background:#14150f;color:#fff;border:0;border-radius:6px;font:inherit;font-weight:600;cursor:pointer}
.btn-p:hover:not(:disabled){background:#00a800}
.btn-p:disabled{opacity:.5;cursor:not-allowed}
.btn-s{padding:11px 20px;background:#fff;color:#14150f;border:1px solid #cfcec2;border-radius:6px;font:inherit;font-weight:600;cursor:pointer}
.btn-s:hover{border-color:#00a800;color:#00a800}
.linkbtn{background:none;border:0;color:var(--green-link);font:inherit;font-weight:600;cursor:pointer;padding:0;text-decoration:underline}
.msg{padding:12px 14px;border-radius:6px;margin-bottom:16px;font-size:.93rem;line-height:1.5}
.msg-err{background:#FDF0EC;border:1px solid #E8B4A4;color:#9A3412}
.msg-ok{background:#EFF6F1;border:1px solid #b9d6c4;color:#00a800}
.summ{background:#F4F6F1;border:1px solid #dfe3d8;border-radius:9px;padding:22px 24px;position:sticky;top:20px}
.summ h2{font-size:1.05rem;margin:0 0 14px}
.sline{display:flex;justify-content:space-between;gap:12px;padding:8px 0;font-size:.92rem;color:#3a3d33}
.sline.tot{border-top:1px solid #dfe3d8;margin-top:8px;padding-top:14px;font-size:1.15rem;font-weight:700;color:#14150f}
.citem{display:flex;justify-content:space-between;gap:12px;padding:11px 0;border-bottom:1px solid #e6e9df;font-size:.92rem}
.citem:last-of-type{border-bottom:0}
.citem .qty{color:var(--ink-muted)}
.ship-opt{display:flex;align-items:center;gap:11px;border:1px solid #cfcec2;border-radius:7px;padding:13px 15px;margin-bottom:9px;cursor:pointer}
.ship-opt:hover{border-color:#00a800}
.ship-opt.on{border-color:#00a800;background:#F4F6F1;box-shadow:inset 3px 0 0 #00a800}
.ship-opt input{margin:0}
.ship-opt .t{flex:1;font-weight:600;font-size:.94rem}
.ship-opt .p{font-weight:700}
.steps{display:flex;gap:8px;margin-bottom:26px;flex-wrap:wrap}
.steps span{font-size:.78rem;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-muted);padding:6px 12px;border-radius:99px;background:#f0f1ea}
.steps span.on{background:#14150f;color:#fff}
.steps span.done{background:#EFF6F1;color:var(--green-link)}
.tabs{display:flex;gap:4px;margin-bottom:22px;border-bottom:1px solid #dfe3d8}
.tabs button{background:none;border:0;padding:11px 18px;font:inherit;font-weight:600;color:var(--ink-muted);cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-1px}
.tabs button.on{color:#14150f;border-bottom-color:#00a800}
.ordrow{border:1px solid #dfe3d8;border-radius:8px;padding:16px 18px;margin-bottom:12px}
.ordrow .top{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:8px}
.ordrow .num{font-weight:700}
.ordrow .st{font-size:.82rem;text-transform:uppercase;letter-spacing:.05em;color:#00a800;background:#EFF6F1;padding:3px 10px;border-radius:99px}
.ordrow .li{font-size:.9rem;color:#5d6151;padding:3px 0}
.empty{text-align:center;padding:44px 20px;color:var(--ink-muted)}
.pay-note{background:#F4F6F1;border:1px solid #dfe3d8;border-radius:7px;padding:14px 16px;font-size:.9rem;line-height:1.6;color:#3a3d33;margin-bottom:18px}
.spin{display:inline-block;width:15px;height:15px;border:2px solid rgba(255,255,255,.35);border-top-color:#fff;border-radius:50%;animation:sp .7s linear infinite;vertical-align:-2px;margin-right:7px}
@keyframes sp{to{transform:rotate(360deg)}}

