(function(){
  var A = window.GreenhseAccount, C = window.GreenhseCheckout;
  var $ = function(s){ return document.querySelector(s); };
  var addr = null, methods = [], payMethods = [];

  function say(t,k){
    var el=$('#co-msg');
    if(!t){ el.innerHTML=''; return; }
    el.innerHTML='<div class="msg msg-'+(k||'err')+'">'+t+'</div>';
    el.scrollIntoView({block:'nearest'});
  }
  function human(e){
    if(e && e.message==='SESSION_EXPIRED') return 'Your session timed out. <a href="/account/?next=%2Fcheckout%2F">Sign in again</a> — your cart is safe.';
    if(!navigator.onLine) return 'You appear to be offline. Check your connection and try again.';
    return (e&&e.message) || 'Something went wrong. Please try again.';
  }
  function busy(b,on,l){ b.disabled=on;
    if(on){ b.dataset.was=b.innerHTML; b.innerHTML='<span class="spin"></span>'+(l||'Working…'); }
    else if(b.dataset.was){ b.innerHTML=b.dataset.was; } }
  function esc(s){ return String(s==null?'':s).replace(/[&<>"]/g,function(c){
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
  var money = C.money;

  function step(n){
    ['s1','s2','s3'].forEach(function(id,i){
      var el=$('#'+id);
      el.classList.toggle('on', i===n-1);
      el.classList.toggle('done', i<n-1);
    });
    $('#form-del').hidden  = n!==1;
    $('#form-ship').hidden = n!==2;
    $('#form-pay').hidden  = n!==3;
    say('');
    window.scrollTo({top:0,behavior:'smooth'});
  }

  function renderSummary(cart){
    $('#sum-items').innerHTML = (cart.items||[]).map(function(i){
      return '<div class="citem"><span>'+esc(i.product.name)+
        ' <span class="qty">× '+i.quantity+'</span></span>'+
        '<b>'+money(i.prices.row_total.value)+'</b></div>';
    }).join('');
    var p = cart.prices||{}, sa=(cart.shipping_addresses||[])[0];
    var rows='';
    if(p.subtotal_excluding_tax) rows+='<div class="sline"><span>Subtotal (ex GST)</span><span>'+money(p.subtotal_excluding_tax.value)+'</span></div>';
    if(sa && sa.selected_shipping_method) rows+='<div class="sline"><span>'+esc(sa.selected_shipping_method.method_title)+'</span><span>'+money(sa.selected_shipping_method.amount.value)+'</span></div>';
    (p.applied_taxes||[]).forEach(function(t){
      rows+='<div class="sline"><span>'+esc(t.label)+'</span><span>'+money(t.amount.value)+'</span></div>';
    });
    if(p.grand_total) rows+='<div class="sline tot"><span>Total</span><span>'+money(p.grand_total.value)+'</span></div>';
    $('#sum-totals').innerHTML = rows;
  }

  function load(){
    return C.cart().then(function(cart){
      if(!cart || !cart.items || !cart.items.length){
        $('#emptycart').hidden=false; $('#co-body').hidden=true; return null;
      }
      $('#emptycart').hidden=true; $('#co-body').hidden=false;
      renderSummary(cart);
      payMethods = cart.available_payment_methods||[];
      return cart;
    });
  }

  /* ---- step 1: address ---- */
  $('#form-del').onsubmit = function(e){
    e.preventDefault();
    var b=$('#del-go'); busy(b,true,'Checking delivery…');
    addr = {
      firstname:$('#c-first').value.trim(), lastname:$('#c-last').value.trim(),
      company:$('#c-co').value.trim(), street1:$('#c-st').value.trim(),
      street2:$('#c-st2').value.trim(), city:$('#c-city').value.trim(),
      postcode:$('#c-pc').value.trim(), region:$('#c-state').value,
      telephone:$('#c-tel').value.trim()
    };
    /* A signed-in customer's cart already carries their email, so the
       address is the only thing this step needs to send. */
    C.setShippingAddress(addr)
      .then(function(ms){
        methods = ms||[];
        if(!methods.length){
          busy(b,false);
          say('We could not find a delivery option for that address. Check the postcode, or call us on (08) 9297 2969.');
          return;
        }
        $('#ship-opts').innerHTML = methods.map(function(m,i){
          return '<label class="ship-opt'+(i===0?' on':'')+'">'+
            '<input type="radio" name="sm" value="'+i+'"'+(i===0?' checked':'')+'>'+
            '<span class="t">'+esc(m.method_title)+'</span>'+
            '<span class="p">'+(m.amount.value>0?money(m.amount.value):'Free')+'</span></label>';
        }).join('');
        $('#ship-opts').querySelectorAll('.ship-opt').forEach(function(el){
          el.onclick=function(){
            $('#ship-opts').querySelectorAll('.ship-opt').forEach(function(x){x.classList.remove('on');});
            el.classList.add('on');
          };
        });
        busy(b,false); step(2);
      })
      .catch(function(err){ busy(b,false); say(human(err)); });
  };

  /* ---- step 2: shipping method ---- */
  $('#ship-back').onclick=function(){ step(1); };
  $('#form-ship').onsubmit = function(e){
    e.preventDefault();
    var sel = $('#ship-opts').querySelector('input[name=sm]:checked');
    if(!sel) return;
    var m = methods[Number(sel.value)];
    var b=$('#ship-go'); busy(b,true,'Saving…');
    C.setShippingMethod(m.carrier_code, m.method_code)
      .then(function(){ return C.setBillingSameAsShipping(addr); })
      .then(load)
      .then(function(){
        $('#pay-methods').innerHTML = payMethods.length
          ? payMethods.map(function(p,i){
              return '<label class="ship-opt'+(i===0?' on':'')+'">'+
                '<input type="radio" name="pm" value="'+esc(p.code)+'"'+(i===0?' checked':'')+'>'+
                '<span class="t">'+esc(p.title)+'</span></label>'; }).join('')
          : '<p class="hint">No payment method is available for this order. Please call us on (08) 9297 2969.</p>';
        busy(b,false); step(3);
      })
      .catch(function(err){ busy(b,false); say(human(err)); });
  };

  /* ---- step 3: place order ---- */
  $('#pay-back').onclick=function(){ step(2); };
  $('#form-pay').onsubmit = function(e){
    e.preventDefault();
    var sel = $('#pay-methods').querySelector('input[name=pm]:checked');
    if(!sel){ say('Choose a payment method.'); return; }
    var b=$('#pay-go'); busy(b,true,'Placing your order…');
    C.setPayment(sel.value)
      .then(function(){ return C.placeOrder(); })
      .then(function(r){
        /* Remember the order so the return page can confirm it even if the
           customer comes back in a fresh tab. */
        try{ sessionStorage.setItem('greenhse_last_order', r.orderNumber); }catch(x){}
        if(r.redirectUrl){ location.href = r.redirectUrl; return; }
        /* No hosted page came back — the order exists but is unpaid, so send
           them somewhere that says exactly that rather than a false success. */
        location.href = '/order-complete/?order='+encodeURIComponent(r.orderNumber)+'&noredirect=1';
      })
      .catch(function(err){ busy(b,false); say(human(err)); });
  };

  /* ---- boot ---- */
  if(!A.signedIn()){
    $('#gate').hidden=false;
  } else {
    load().catch(function(err){
      $('#co-body').hidden=true;
      say(human(err));
    });
  }
})();
